window.DIGEST.foryou.push(...[{"id": "2112631749717180691", "url": "https://x.com/feeldotcash/status/2112631749717180691", "text": "Anthropic was valued at $965B in May.\n\nReports have put its potential IPO valuation as high as $2T.\n\nGet exposure before it goes public.\n\nTap. Done.\n\nhttps://feel.cash/stocks/anthropic", "name": "Feel.cash", "handle": "feeldotcash", "avatar": "https://pbs.twimg.com/profile_images/2090009813426077696/-P_b4T8v_200x200.jpg", "likes": 18, "rts": 5, "replies": 1, "views": 1330, "ts": 1792525634, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112631280630104064/vid/avc1/1370x720/8zYA-JprxmIPZXfa.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112631280630104064/vid/avc1/2560x1344/mLx4CPIz0e-S_KnY.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112631280630104064/img/VuSa82w8Q9AnDZAv.jpg", "dur": 8}], "quote": {"id": "2112249206748373306", "url": "https://x.com/FT/status/2112249206748373306", "text": "Anthropic’s planned IPO could be the biggest stock market debut in history. What does it mean for investors, AI and the tech industry as a whole? Our reporters will answer your questions: https://ft.trib.al/OAzDhvM", "name": "Financial Times", "handle": "FT", "avatar": "https://pbs.twimg.com/profile_images/931156393108885504/EqEMtLhM_200x200.jpg", "likes": 104, "rts": 16, "replies": 13, "views": 27672, "ts": 1792434429, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVA3dBzXwAAAcDU.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "skim"}, {"id": "2112673946466476234", "url": "https://x.com/0xDevShah/status/2112673946466476234", "text": "if everyone had infinite tokens and infinite tokens/sec, i think everyone would be a researcher. curiosity and discovery are deeply human. it's just that most people don't have the patience, time, or resources to spend years chasing a question. but what if they didn't have to wait years?\n\nnext year, we'll run today's frontier models on consumer GPUs. in 2 years, we'll have AGI in a zip file.\n\nimagine billions of people suddenly have the ability to pursue their curiosity and make discoveries. when everyone can be a researcher, they'll need a research lab. this is ArkenOS!", "name": "Dev Shah", "handle": "0xDevShah", "avatar": "https://pbs.twimg.com/profile_images/1859072760938721280/eihad2RU_200x200.jpg", "likes": 15, "rts": 3, "replies": 3, "views": 766, "ts": 1792535695, "media": [], "quote": {"id": "2112032537652650022", "url": "https://x.com/0xDevShah/status/2112032537652650022", "text": "Introducing Optimus-1, the first swarm harness for autonomous research. Generally available in ArkenOS, starting now.\n\nOptimus-1 lets ArkenOS spawn a swarm that runs the entire discovery loop on hard research problems autonomously. The harness samples the hypothesis space in parallel and works the tails of the distribution, chasing every anomaly until it resolves into an artifact or a discovery. We want every researcher to have a lab of their own, and to see how far their curiosity can go.\n\nUnlike coding agents, Optimus-1 is designed for long-horizon discovery, where most branches fail, and the hard part is knowing which result to believe. It keeps what replicates and keeps pushing past the edge of what's known.\n\nWe're still early, but ArkenOS is helping hundreds of teams, from RL environments and data labs to frontier research groups, scale the alpha in their core research.\n\nIf you're working on a hard research problem and want to try it, my DMs are open. I'd love to hear what you'd point it at.", "name": "Dev Shah", "handle": "0xDevShah", "avatar": "https://pbs.twimg.com/profile_images/1859072760938721280/eihad2RU_200x200.jpg", "likes": 664, "rts": 72, "replies": 41, "views": 37409, "ts": 1792382771, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112032208794103808/vid/avc1/1280x720/WGxACKktRuHfa15I.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112032208794103808/vid/avc1/3840x2160/sC_hWcSCQFtGpQcN.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112032208794103808/img/J0h7jYI_BWxBTwUz.jpg", "dur": 56}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "skim"}, {"id": "2112723776999927811", "url": "https://x.com/0xSigil/status/2112723776999927811", "text": "Bringing more models on device- smaller and smarter @UnderdogAI 🐶", "name": "Sigil Wen", "handle": "0xSigil", "avatar": "https://pbs.twimg.com/profile_images/2101470722094989312/6BV11OZD_200x200.jpg", "likes": 14, "rts": 2, "replies": 3, "views": 1866, "ts": 1792547575, "media": [], "quote": {"id": "2112256989086859699", "url": "https://x.com/NVIDIARTXSpark/status/2112256989086859699", "text": "Love seeing what @UnderdogAI is bringing to RTX Spark. Their Saluki 27B model brings fast, private personal AI to your laptop in under 8GB of memory. 👏", "name": "NVIDIA RTX Spark", "handle": "NVIDIARTXSpark", "avatar": "https://pbs.twimg.com/profile_images/2061303426479431680/BDJQPK6Q_200x200.jpg", "likes": 131, "rts": 13, "replies": 3, "views": 11410, "ts": 1792436284, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "skim"}, {"id": "2112575874650542214", "url": "https://x.com/urdeaintech/status/2112575874650542214", "text": "Voxel is a home robot built around the small things.\n\n→ Resets the house after a mess\n→ Finds your phone or wallet\n→ Fetches what you need\n\nThat's where a home robot starts to make sense", "name": "Samuel Urdea", "handle": "urdeaintech", "avatar": "https://pbs.twimg.com/profile_images/2092899894218416128/ZypwJ5s7_200x200.jpg", "likes": 31, "rts": 3, "replies": 1, "views": 651, "ts": 1792512312, "media": [], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1850860, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.05, "thread": [], "tier": "skim"}, {"id": "2112378276681580942", "url": "https://x.com/WayOfMenn/status/2112378276681580942", "text": "Jensen Huang on The smartest person he's ever met:", "name": "Way of Men", "handle": "WayOfMenn", "avatar": "https://pbs.twimg.com/profile_images/2062051683539271680/67GXnHBz_200x200.jpg", "likes": 9215, "rts": 957, "replies": 182, "views": 983985, "ts": 1792465201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111366694308655104/vid/avc1/540x360/zFf7M_E6RMtJS6NN.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2111366694308655104/vid/avc1/720x480/FQE6Wp-064EgVEi1.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111366694308655104/img/YQ97JjsLajU8-L1c.jpg", "dur": 124}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112522086014972238", "url": "https://x.com/borrhensaidi/status/2112522086014972238", "text": "We’re giving away 5+ Claude Max annual subscriptions. Yes, ANNUAL. 👀\n\nSwarmPane builds, ships, and gives back. This is just the beginning. Join the swarm. More surprises incoming.\n\nhttps://swarmpane.com/", "name": "borhen saidi", "handle": "borrhensaidi", "avatar": "https://pbs.twimg.com/profile_images/2085022334029533184/fvWmeUEb_200x200.jpg", "likes": 38, "rts": 0, "replies": 5, "views": 16605, "ts": 1792499488, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112522036895494144/vid/avc1/1382x720/cvwtfi-V-UFqVel2.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112522036895494144/vid/avc1/1920x1000/2KtoNKRse1i9rJ9z.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112522036895494144/img/YFgKLz5OehRyOPn8.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112604762289946819", "url": "https://x.com/lovart_ai/status/2112604762289946819", "text": "Off-brand details, caught before you deliver.\n\nCanvas Check-up: Arti flags what doesn't match your brand on the canvas, and you fix it in one click.\n\nArti, your first personal design agent, has memory and takes initiative. Now in Lovart 2.0.\n\n#BuiltWithLovart", "name": "Lovart AI", "handle": "lovart_ai", "avatar": "https://pbs.twimg.com/profile_images/2065372538763694080/KSuXj3OU_200x200.jpg", "likes": 27, "rts": 2, "replies": 2, "views": 1256, "ts": 1792519200, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112591903351062528/vid/avc1/1280x720/6DYZadWGFg2I4Dbg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112591903351062528/vid/avc1/1920x1080/l3N0oP3Zh0xs1dW_.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVFytYLX0AA-ztl.jpg", "dur": 17}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112574729575932075", "url": "https://x.com/thisiskp_/status/2112574729575932075", "text": "\"The next leap in AI coding won't come from OpenAI or Anthropic.\" Big bet with a $5.5M seed behind it..\n\nBut they're right about one thing. Your sessions are the most valuable training data you own, and right now they just disappear.\n\nHyped to see this one open source 💪", "name": "KP", "handle": "thisiskp_", "avatar": "https://pbs.twimg.com/profile_images/1288449070344937473/fKlvccnM_200x200.jpg", "likes": 20, "rts": 3, "replies": 6, "views": 3073, "ts": 1792512039, "media": [], "quote": {"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425746, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112343898391552235", "url": "https://x.com/PyTorch/status/2112343898391552235", "text": "#PyTorchCon North America 2026 starts tomorrow in San Jose, bringing the open source AI community together to accelerate open intelligence.\n\nAcross PyTorch, @vllm_project, @DeepSpeedAI, @raydistributed, Helion, and Safetensors, our program explores the full AI stack, from bare metal infrastructure to applications and agent-based systems, through technical talks, hands-on workshops, and candid conversations.\n\nTomorrow and Wednesday, October 20–21, the program spans seven tracks: Applications, Core PyTorch, Inference, Introduction, Kernel Engineering, Responsible AI, and Training.\n\nKeynote speakers include @sparkycollier (PyTorch Foundation); @cmazzaanthony (@Shopify); @albanDesmaison, Edward Yang, Jana van Greunen, and Zongwei Zhou (@Meta); @clattner_llvm (@Qualcomm); @istoica05 (@UCBerkeley / @anyscalecompute); Robert Hundt (@amazon); @sarahookr (@adaption_ai); @simon_mo_ (@inferact); Carlos Costa and Priya Nagpurkar (@IBM); Abdullah Gharaibeh and Bill Jia (@googlecloud); Stephen Watt (@RedHat); Ujval Kapasi (@nvidia); Mazin Gilbert (@AgenticAIFdn); Zhipeng Wang (@Google); Rachad Alao (@cohere); Yiwei Song (@CrusoeAI); and @marksaroufim (Core Automation).\n\nBeyond the talks, exchange ideas in Birds of a Feather discussions, ask questions in Meet the Developers sessions, and watch sponsor presentations in the Demo Theater.\n\nTuesday offers more opportunities for conversation: discuss presenters’ work at the evening poster session, connect at the Women & Non-Binary in PyTorch Lunch, or meet Inference Engineering author Philip Kiely at his book signing.\n\nExplore the program: https://events.linuxfoundation.org/pytorch-conference-north-america/program/schedule/\n\nJoin us at #PyTorchCon tomorrow and Wednesday: https://events.linuxfoundation.org/pytorch-conference-north-america/register/", "name": "PyTorch", "handle": "PyTorch", "avatar": "https://pbs.twimg.com/profile_images/1813965160702451712/yXV1vRhr_200x200.jpg", "likes": 44, "rts": 7, "replies": 11, "views": 7422, "ts": 1792457005, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVCNlLjXUAAkK8Y.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112464345728721085", "url": "https://x.com/_ScottCondron/status/2112464345728721085", "text": "Auto-research on idle GPU capacity\n\nEvery idle GPU is spice that isn't flowing. \nAnd the spice must flow.\n\nOne idea to keep your GPUs busy is an auto-research pipeline: a queue of different ideas for agents to try whenever the GPUs are not doing higher priority work.\n\nOn @CoreWeave you can build this from: \n\n- SUNK (Slurm on Kubernetes) to share nodes between priority jobs and agents, with preemption so priority work gets done - GPU sandboxes to run agent-written code in isolation - Spot capacity for cheap extra capacity  - Dedicated inference plus Dynamo agent_hints to rank the agents' own model calls below production traffic\n\nAnd you can see what the agents are doing: traces, evals and training runs in one place.", "name": "Scott Condron", "handle": "_ScottCondron", "avatar": "https://pbs.twimg.com/profile_images/1016982898556141569/R09dBwgv_200x200.jpg", "likes": 48, "rts": 2, "replies": 2, "views": 2750, "ts": 1792485722, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112464308453924864/vid/avc1/720x720/pW9WQVZRl-fcUVOL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112464308453924864/vid/avc1/1440x1440/G3BVENQIR5e4PcZg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112464308453924864/img/ZYcl0RY_pynkIWqf.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112671510913482822", "url": "https://x.com/BBCWorld/status/2112671510913482822", "text": "Alberta's decisive decision to stay in Canada gives Carney backing to take on Trump https://bbc.in/4sdvfcC", "name": "BBC News (World)", "handle": "BBCWorld", "avatar": "https://pbs.twimg.com/profile_images/1529107170448523264/q3VwEx38_200x200.jpg", "likes": 2132, "rts": 331, "replies": 861, "views": 345930, "ts": 1792535114, "media": [], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112628249096593513", "url": "https://x.com/AnnLLarson/status/2112628249096593513", "text": "holy fucking shit", "name": "Ann Larson", "handle": "AnnLLarson", "avatar": "https://pbs.twimg.com/profile_images/2098946083712094208/H_vIW-A__200x200.jpg", "likes": 4485, "rts": 344, "replies": 18, "views": 320260, "ts": 1792524799, "media": [], "quote": {"id": "2112604932797026411", "url": "https://x.com/william_fitz/status/2112604932797026411", "text": "\"Speculative data center debt is being repackaged and sold to pension and retirement funds, university endowments, and other institutional investors in a manner eerily reminiscent of the subprime bubble.\"\n\nhttps://ourfinancialsecurity.org/resources/brace-for-impact-protecting-people-and-the-economy-when-the-ai-bubble-bursts/", "name": "William Fitzgerald", "handle": "william_fitz", "avatar": "https://pbs.twimg.com/profile_images/1868743858303254530/Fg_1fdZb_200x200.jpg", "likes": 4910, "rts": 1131, "replies": 84, "views": 704974, "ts": 1792519240, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112641692998533269", "url": "https://x.com/kushalbyatnal/status/2112641692998533269", "text": "I don't think people realize how good AI-generated documents have gotten\n\nwe built a game so you can see for yourself\n\nsome documents are real, others are fake. can you tell the difference?\n\nhttps://www.extend.ai/fraud-arcade", "name": "Kushal Byatnal", "handle": "kushalbyatnal", "avatar": "https://pbs.twimg.com/profile_images/1225315201311854592/GHIT4gYq_200x200.jpg", "likes": 23, "rts": 2, "replies": 2, "views": 1523, "ts": 1792528005, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112639960558002176/vid/avc1/1280x720/4N3jQm1i-cvEiWuj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112639960558002176/vid/avc1/1920x1080/NtFVVO5R1hCQqP8R.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112639960558002176/img/d6MuSZfPpH4R9SIb.jpg", "dur": 57}], "quote": {"id": "2112221199560536193", "url": "https://x.com/kushalbyatnal/status/2112221199560536193", "text": "AI-generated fake documents grew 500% last year, and humans can no longer tell the difference\n\nThat's why we’re launching Extend Verify, the first document fraud detection API built for agents\n\nVerify catches the fastest growing types of document fraud, including:\n\n- fully AI-generated documents\n- localized AI edits (down to a single modified character)\n- patched text, overlays, and in-painting from Photoshop, PDF editors, and coding agents\n- digital tampering after a document was signed\n- and many more\n\nIn our internal evals, Verify detected over 96% of AI-generated and tampered documents.\n\nVerify is available today: https://www.extend.ai/verify/request-access", "name": "Kushal Byatnal", "handle": "kushalbyatnal", "avatar": "https://pbs.twimg.com/profile_images/1225315201311854592/GHIT4gYq_200x200.jpg", "likes": 191, "rts": 20, "replies": 52, "views": 25179, "ts": 1792427751, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112220772509126659/vid/avc1/1280x720/oKPir6JnEhWZ9Sb6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112220772509126659/vid/avc1/3840x2160/faX5ymXCJHzNZQlR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112220772509126659/img/ydg4Gnovrkk91TCy.jpg", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112722931729981719", "url": "https://x.com/boneGPT/status/2112722931729981719", "text": "the slopcannon loves you\nthank you", "name": "bone", "handle": "boneGPT", "avatar": "https://pbs.twimg.com/profile_images/2006021278281478144/veZLsQq9_200x200.jpg", "likes": 20, "rts": 1, "replies": 1, "views": 758, "ts": 1792547374, "media": [], "quote": {"id": "2112691725286224200", "url": "https://x.com/HeyoPatriot/status/2112691725286224200", "text": "Heyoo, shoutout to the SlopCannon devs and all the wiggas in the group chat, 🐷🎤 Just wanted to say Thank You.  I lurk more than I post, but your nonstop builds, unhinged experiments, and pure love for acceleration pulled me off the sidelines.\n\nmy app drops tonight 👽⚡️ drinks are on me 🍺🇺🇸", "name": "heyopatriot", "handle": "HeyoPatriot", "avatar": "https://pbs.twimg.com/profile_images/1958631581603471360/BYhAar5X_200x200.jpg", "likes": 15, "rts": 3, "replies": 3, "views": 750, "ts": 1792539933, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112691617010188289/vid/avc1/1280x720/XyIy5o29qsDpuTAX.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112691617010188289/vid/avc1/2560x1440/Ns47VGVpMWjPu90d.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112691617010188289/img/bNsTKxQlg3of87FC.jpg", "dur": 113}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112724875874025642", "url": "https://x.com/atulkumarzz/status/2112724875874025642", "text": "Imagine asking your agent who won the game and getting the answer instantly, with the right source to back it up.\n\nThat’s what @youdotcom is bringing with Sportradar. No digging around for scores, no telling your agent where to look. Just ask and get the answer.", "name": "Atul Kumar", "handle": "atulkumarzz", "avatar": "https://pbs.twimg.com/profile_images/1602322477501140992/BJSVHwBm_200x200.jpg", "likes": 7, "rts": 6, "replies": 0, "views": 563, "ts": 1792547837, "media": [], "quote": {"id": "2112631743564165401", "url": "https://x.com/youdotcom/status/2112631743564165401", "text": "Who won the 49ers game last night? 🏈\n\nYour AI agent should already know.\n\nWith @youdotcom 's live answers powered by Sportradar, get real-time sports scores and answers backed by the right source, without having to tell your agent where to look.\n\nTry it for free - https://you.com/platform/playground/web-search?knowledge=core&query=Who+won+the+49ers+game+yesterday%3F%0A", "name": "You.com", "handle": "youdotcom", "avatar": "https://pbs.twimg.com/profile_images/1814006937194795008/LW6Ol2Q1_200x200.png", "likes": 6, "rts": 0, "replies": 0, "views": 851, "ts": 1792525633, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112627741883592706/vid/avc1/720x720/ytGO4yFQXqPypWnA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112627741883592706/vid/avc1/2160x2160/kZ3oOIm2PTsyla8O.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112627741883592706/img/XVwsD0GWOrpjfDGt.jpg", "dur": 8}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112529374855692473", "url": "https://x.com/val_soonafter/status/2112529374855692473", "text": "I never worked with 3D before. Lately, Opus is changing what I thought my limits were.\n\nAI can produce a lot of slop, very efficiently! Poor guidance sets the machine on autopilot.\n\nBUT it can also get you to places you would’ve never gotten by yourself.", "name": "Val Guerra", "handle": "val_soonafter", "avatar": "https://pbs.twimg.com/profile_images/2102463117691338752/-vReGzmb_200x200.jpg", "likes": 41, "rts": 0, "replies": 3, "views": 1527, "ts": 1792501226, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112529286217568256/vid/avc1/1280x720/cIDMkFf0ZG4Kng00.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112529286217568256/vid/avc1/1920x1080/PNPx-WcK1aMEeeBl.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112529286217568256/img/HKdEw57st49Ipz5g.jpg", "dur": 7}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2112691844358262973", "url": "https://x.com/CNN/status/2112691844358262973", "text": "Several Trump administration officials, advisers and close allies describe a toxic mix of jockeying for power and preemptive finger-pointing ahead of the midterms.\n\n\"It's more brutal than any other situation in modern times in the White House,\" said one Trump ally. \"You can't trust anybody here.\" https://cnn.it/4zKoeTc", "name": "CNN", "handle": "CNN", "avatar": "https://pbs.twimg.com/profile_images/1669780523911110656/K9gaaM1g_200x200.jpg", "likes": 1873, "rts": 505, "replies": 586, "views": 743588, "ts": 1792539962, "media": [], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.04, "thread": [], "tier": "skim"}, {"id": "2111838943016833235", "url": "https://x.com/elonmusk/status/2111838943016833235", "text": "The new Tesla Roadster accelerates faster than a fighter jet taking off from an aircraft carrier", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 44673, "rts": 5093, "replies": 3498, "views": 2943609, "ts": 1792336614, "media": [], "quote": {"id": "2111730102618972636", "url": "https://x.com/XFreeze/status/2111730102618972636", "text": "The new Tesla Roadster produces more thrust than an F-16 fighter jet at military power\n\nRoadster Thrust augment:\n>80 kN (~18,000 lbf)\n\nF-16 with F100-PW-229:\n~79.2 kN (~17,800 lbf) without afterburner\n\nTesla packed enough cold-gas thrust into a car that exceeds the non-afterburning thrust of an F-16 engine\n\nWith afterburner, the F-16 exceeds at ~130 kN\n\nBut the fact this comparison even exists is insane\n\nTesla just pushed automotive engineering deep into aerospace territory", "name": "X Freeze", "handle": "XFreeze", "avatar": "https://pbs.twimg.com/profile_images/1876785200010539008/2_HFJjq9_200x200.jpg", "likes": 2734, "rts": 345, "replies": 193, "views": 2019648, "ts": 1792310665, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111730001943154688/vid/avc1/720x720/z4yJK-E034o81MTG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111730001943154688/vid/avc1/2160x2160/Qnfp2Y_plZivkL8I.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111730001943154688/img/VO4c1JTFmkAQUGSO.jpg", "dur": 18}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112204695456616829", "url": "https://x.com/AskPerplexity/status/2112204695456616829", "text": "Computer built an interactive Lord of the Rings map that tracks the journeys of the main characters across Middle-earth, chapter by chapter.\n\nIt built the map from scratch by placing 179 locations, 41 rivers, and 23 roads, baked the ranges into a heightfield, inked the relief in a GLSL shader, and plotted 537 journey legs.\n\nTry it: http://middle-earth.pplx.app", "name": "Computer", "handle": "AskPerplexity", "avatar": "https://pbs.twimg.com/profile_images/2028889294174380032/1hOF3gRi_200x200.jpg", "likes": 103, "rts": 4, "replies": 9, "views": 12048, "ts": 1792423816, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112204636115574784/vid/avc1/1280x720/9YJGMOh72xnnpuSj.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112204636115574784/vid/avc1/1920x1080/q5SfnCqg18XDuEq6.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112204636115574784/img/mE_MHCFp0zRCV3v9.jpg", "dur": 97}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112458848971952580", "url": "https://x.com/AiHubMix/status/2112458848971952580", "text": "MiniMax M3.1 Flash is kind of ridiculous at 3D frontend\n\n$1.62 for an entire autumn valley\n\nBuilding a scene like this used to mean:\n> hiring a 3D artist\n> modeling, texturing, lighting, one step at a time\n> setting up an engine just to walk around in it\n> and often ending up with a single still render\n\nAmberbrook, today:\n> one prompt\n> a stone watermill, its wheel slowly turning\n> a stream running under a stone arch bridge into a pond\n> an ivy-covered woodcutter's hut tucked at the edge of the woods\n> runs in a browser tab: drag, zoom, pan, or hit Tour and the camera flies you through 5 stops\n\nThe details are what got me\n\nSmoke drifting from the chimney, warm light in the windows, the whole mill reflected in the pond\nAnd an axe still stuck in a tree stump\n\nTry MiniMax M3.1 Flash on AIHubMix: https://aihubmix.com", "name": "AIHubmix", "handle": "AiHubMix", "avatar": "https://pbs.twimg.com/profile_images/2005111189165236224/QuN045cN_200x200.jpg", "likes": 36, "rts": 4, "replies": 5, "views": 2919, "ts": 1792484411, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112455834781487104/vid/avc1/1280x720/IvCteWT6tbi4tyI5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112455834781487104/vid/avc1/2560x1440/v_M8d5Z-AM_BlkTR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112455834781487104/img/pTwu_6y1iYPIjLxJ.jpg", "dur": 31}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112612481826979846", "url": "https://x.com/harleyfoote_/status/2112612481826979846", "text": "Software IP died last week.\n\nNot gradually. Not eventually. Headless agents just made the entire business model evaporate.\n▶ Full video: https://www.youtube.com/watch?v=xIFMwhvvUUo — via The AI Daily Brief: Artificial Intelligence News", "name": "Harley Lewis Foote", "handle": "harleyfoote_", "avatar": "https://pbs.twimg.com/profile_images/2080658812382449664/VF5NORY-_200x200.jpg", "likes": 31, "rts": 0, "replies": 2, "views": 519, "ts": 1792521040, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112612424792604672/vid/avc1/640x360/bffn4bfTGL7Aqvse.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112612424792604672/vid/avc1/1280x720/FZKGkiam570myU4V.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112612424792604672/img/BQYGkfWWxJqyhFCw.jpg", "dur": 45}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112605757975966149", "url": "https://x.com/Arj_786/status/2112605757975966149", "text": "Open-source OCR has a new leader: OXR\n\n🔹 olmOCR-Bench · OmniDocBench · DocParsingBench winner\n🔹 Speed champ, single RTX PRO 6000\n🔹 1.7x LightOnOCR-2-1B\n\nFormulas + tables. Swap the layout model. RSI + parallel ordering inside.\n\n👉 https://github.com/SoMarkAI/OXR", "name": "Aria Arooj", "handle": "Arj_786", "avatar": "https://pbs.twimg.com/profile_images/2023131891621339136/xHIj4IXT_200x200.jpg", "likes": 6, "rts": 6, "replies": 6, "views": 191, "ts": 1792519437, "media": [], "quote": {"id": "2112574994152636502", "url": "https://x.com/somarkai/status/2112574994152636502", "text": "Beyond OCR. Meet OXR.\nOnly 1.3B. Open source.\n\n#1 on olmOCR-Bench, OmniDocBench & DocParsingBench🏆\n#1 in parsing speed among open-source models⚡\n\nRSI-powered. A first in document parsing.\nTurn documents into Agent-Friendly data.\n\nIf OXR helps, give us a star on GitHub! 🌟", "name": "SoMark", "handle": "somarkai", "avatar": "https://pbs.twimg.com/profile_images/2054830841197690880/72QHhpxV_200x200.jpg", "likes": 64, "rts": 15, "replies": 19, "views": 235899, "ts": 1792512103, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112574131791097857/vid/avc1/720x720/sb4cgnPfueTkA0vb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112574131791097857/vid/avc1/1200x1200/ohWAOZCkHsVrYIVo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112574131791097857/img/WA95Dj7H23zc6QHc.jpg", "dur": 18}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112522397362606110", "url": "https://x.com/harshmadhusudan/status/2112522397362606110", "text": "Thank you Dhirubhai and Mukesh Ambani. Thank you to IOCL, HPCL and BPCL etc. Thank you to all engineers who worked on some of the most complex refineries in the world. While the world faces terrible diesel crack spreads, we earn valuable foreign exchange thanks to our refineries.", "name": "Harsh Gupta Madhusudan", "handle": "harshmadhusudan", "avatar": "https://pbs.twimg.com/profile_images/1958379378062311424/WSWsCxka_200x200.jpg", "likes": 5408, "rts": 732, "replies": 30, "views": 58219, "ts": 1792499562, "media": [], "quote": {"id": "2112489145348264263", "url": "https://x.com/siddhantvm/status/2112489145348264263", "text": "MARCO RUBIO : India is a refining superpower", "name": "Siddhant Mishra", "handle": "siddhantvm", "avatar": "https://pbs.twimg.com/profile_images/2025076458264444930/LSqUmry9_200x200.jpg", "likes": 369, "rts": 54, "replies": 13, "views": 152475, "ts": 1792491635, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112614178980843765", "url": "https://x.com/yatharthmann/status/2112614178980843765", "text": "Wow! Elon Musk fired a Muslim just because of his religion! \n\nHe's such an Islamophobe!", "name": "Yatharth Mann", "handle": "yatharthmann", "avatar": "https://pbs.twimg.com/profile_images/2041184115131916288/XdogQZvG_200x200.jpg", "likes": 3378, "rts": 326, "replies": 679, "views": 511890, "ts": 1792521445, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112611845320404992/vid/avc1/640x360/6rDvmY6Y033RVFEt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112611845320404992/vid/avc1/1280x720/firPbz6y4rGxiD8t.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112611845320404992/img/tz7c4BTeEkdPPgao.jpg", "dur": 42}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112596772099064117", "url": "https://x.com/urdeaintech/status/2112596772099064117", "text": "Re-explaining context every single day gets old fast.\n\n➔ Having local memory on your Mac changes everything. \n\n➔ It quietly handles drafts and notes while you sleep.\n\nGreat approach by @Shogun_AI and @toruai.", "name": "Samuel Urdea", "handle": "urdeaintech", "avatar": "https://pbs.twimg.com/profile_images/2092899894218416128/ZypwJ5s7_200x200.jpg", "likes": 28, "rts": 3, "replies": 0, "views": 633, "ts": 1792517295, "media": [], "quote": {"id": "2112593925114634603", "url": "https://x.com/toruai/status/2112593925114634603", "text": "Your AI forgets you every time you close it. \n\nEvery assistant today works the same way. You open a chat, re-explain your job, get an answer, and start from zero tomorrow.  Smart, sure. Useful? \n\nOnly while you're typing.  It doesn't know about yesterday's meeting. It does nothing until you ask. \n\nAnd most of them want your whole work history on someone else's server to remember it.  \n\nWe built Shogun for exactly this.\n@Shogun_AI_\nShogun is a private, local-first memory on your Mac. It remembers your meetings, drafts, and docs, then works while you sleep: prepares replies, organizes what it can, writes your daily brief.  You wake up, review, approve. \n\nNothing goes out without your yes. Your personal AGI, always running on your computer.\n\nThe first 500 users get a month free.\n\nFollow @Shogun_AI_ @toruai\nand comment 『ShogunAI』", "name": "Toru.T", "handle": "toruai", "avatar": "https://pbs.twimg.com/profile_images/2077537203614605312/9S3FfAKk_200x200.jpg", "likes": 87, "rts": 44, "replies": 51, "views": 21629, "ts": 1792516616, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112592786579189760/vid/avc1/1280x720/kJpS_CWA4h8yYETb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112592786579189760/vid/avc1/3840x2160/0kg65h_VD_oWzGWC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112592786579189760/img/uhPh59whRg063POW.jpg", "dur": 132}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.03, "thread": [], "tier": "skim"}, {"id": "2112569779601178926", "url": "https://x.com/kaif9998/status/2112569779601178926", "text": "an orange box, two pixel eyes and a line for a mouth\n\nthat's the whole face, a Voxel by @roboticscorp has more personality than most apps i've designed\n\nthat's what happens when a robotics team brings in Pixar advisors", "name": "Kaif", "handle": "kaif9998", "avatar": "https://pbs.twimg.com/profile_images/2012834364862705664/hWdVyUJE_200x200.jpg", "likes": 16, "rts": 2, "replies": 9, "views": 461, "ts": 1792510859, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1850860, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112265788963110920", "url": "https://x.com/runable_hq/status/2112265788963110920", "text": "FLUX.3 Max is seriously amazing 🔥\n\nSide by side with Seedance 2.5, \nthe quality is surprisingly close.\n\n→ 22× faster in my test\n→ ~5× cheaper at comparable 720p pricing on Layer\n→ Native audio\n→ Up to 20-second videos\n\nThe speed difference is WILD.", "name": "Runable", "handle": "runable_hq", "avatar": "https://pbs.twimg.com/profile_images/2091784345648336896/ppDHg8vE_200x200.jpg", "likes": 69, "rts": 6, "replies": 10, "views": 12722, "ts": 1792438382, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112264811316916224/vid/avc1/1280x720/SVNnTQjR1J2LYZ5H.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112264811316916224/vid/avc1/1920x1080/fq8tYdWtUBgzbXBD.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112264811316916224/img/3mFUO8V2WlufpDTH.jpg", "dur": 20}], "quote": {"id": "2112255353677328415", "url": "https://x.com/bfl_ai/status/2112255353677328415", "text": "Introducing FLUX 3 Max.\n\nFastest in the west. Fast enough to try anything. And everything.\n\nGenerate a 10-second video in 12 seconds.\n\nTied for #1 in image-to-video. 22× faster than Seedance 2.5 at the same quality.\n\nFLUX 3 is a model designed for customization. @fal adapted and optimized it to create FLUX 3 Max.", "name": "Black Forest Labs", "handle": "bfl_ai", "avatar": "https://pbs.twimg.com/profile_images/1954888731053142016/NDyG-4-j_200x200.jpg", "likes": 955, "rts": 106, "replies": 91, "views": 65906, "ts": 1792435894, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/720x720/6c2tLuZIRfEMaRz7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/2160x2160/5hWxA_d-ViViLNG2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112238793139044352/img/1Uf4xVFGip9CN4_K.jpg", "dur": 15}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112483780187320684", "url": "https://x.com/SkyNews/status/2112483780187320684", "text": "BREAKING: Multiple online services are down or 'experiencing issues.'\n \nGoogle Cloud has reported \"issues\" in its western Europe region affecting dozens of websites, including; Revolut, Royal Mail and HSBC.\n \nLatest updates ➡️ https://trib.al/M16q5UZ\n\n📺 Sky 501", "name": "Sky News", "handle": "SkyNews", "avatar": "https://pbs.twimg.com/profile_images/1604907328242962433/P_79at43_200x200.jpg", "likes": 3452, "rts": 1547, "replies": 233, "views": 1441649, "ts": 1792490355, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112483638566629376/vid/avc1/1280x720/x1PxUU10fYoB3AzR.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112483638566629376/vid/avc1/1920x1080/lSZuJN5mJdRJiIO2.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVEMvlaXsAEzmhd.jpg", "dur": 128}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112569403971981406", "url": "https://x.com/GreylockVC/status/2112569403971981406", "text": "Founders learn to obsess over product-market fit. Greylock Partner @jerrychen says to look just as hard at who should write the first check. He calls it founder-VC fit.\n\nIn 2018, Jerry read a technical blog about M3, an open source project built at Uber, led by engineers Rob Skillington @roskilli and Martin Mao @martin_c_mao. At the time, they hadn’t even decided to start a company.\n\nWhat followed was a five-month courtship.\n\nJerry was trying to convince Martin and Rob to take his investment. As first-time founders, they were diligencing him just as closely.\n\nMartin sent him an 85-page business plan to see who would really do the work, understand the technology, and align with where they wanted to take it.\n\nRob and Martin eventually started @chronosphereio, with M3 as its technical foundation and Jerry wrote the company’s first check.\n\nSeven years later, the company was acquired by @PaloAltoNtwks for $3.35B.  \n\nFor founders, choosing the early investor can shape the company’s trajectory for years. The relationship deserves as much diligence as the financing.\n\nFull story in the comments.", "name": "Greylock Partners", "handle": "GreylockVC", "avatar": "https://pbs.twimg.com/profile_images/2076850957607133184/PuYJpvfw_200x200.jpg", "likes": 19, "rts": 3, "replies": 6, "views": 3858, "ts": 1792510770, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112569355091488768/vid/avc1/1280x720/eUce8BZCJXhZoEys.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112569355091488768/vid/avc1/3840x2160/G_RDROx9sNzGSZYU.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVFaxmmaYAA2Wr2.jpg", "dur": 49}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112677952072847476", "url": "https://x.com/vpj/status/2112677952072847476", "text": "Amazing work by @parth_29 @joeyxhong @saurabh_shah2 @YuchenHe07 @ericzelikman", "name": "vpj", "handle": "vpj", "avatar": "https://pbs.twimg.com/profile_images/1725934245510553600/E0ly56Rd_200x200.jpg", "likes": 23, "rts": 1, "replies": 1, "views": 814, "ts": 1792536650, "media": [], "quote": {"id": "2112674550907552137", "url": "https://x.com/humansand/status/2112674550907552137", "text": "No one changes the world alone\nIntroducing Ampersand - the first model built for us. Ampersand is a collaborator trained to help people achieve their individual and collective goals. In multi-month simulations, users collaborating with Ampersand accomplished more than with Fable and other frontier models\nAvailable to everyone through our API", "name": "humans&", "handle": "humansand", "avatar": "https://pbs.twimg.com/profile_images/2013582555933478912/JKuMlTII_200x200.jpg", "likes": 801, "rts": 96, "replies": 70, "views": 115277, "ts": 1792535839, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1280x720/diVwgP2fN9mNUINm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1920x1080/BeqyLOSxKBxRevC6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664844772278272/img/eMd4u-rAwyUJpqWU.jpg", "dur": 32}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112582771306897651", "url": "https://x.com/RylanSchaeffer/status/2112582771306897651", "text": "Congratulations to @exnx @athmsx and the entire Radical team!!\n\nI remember when Eric and I had coffee in Gradient Canopy about whether he should take the leap from a cozy AI lab to this crazy moonshot. I never had any doubt that he and the team would crush it ❤️‍🔥", "name": "Rylan Schaeffer", "handle": "RylanSchaeffer", "avatar": "https://pbs.twimg.com/profile_images/2077436034716139520/Ys5IJj-e_200x200.jpg", "likes": 30, "rts": 2, "replies": 1, "views": 2739, "ts": 1792513957, "media": [], "quote": {"id": "2112580926651904379", "url": "https://x.com/exnx/status/2112580926651904379", "text": "Introducing Omnii-1, our most powerful genome language model, and a major step toward general biological intelligence\n\nIn a world first, Omnii-1 designed the first AI-generated bacteriophages to be administered to a human patient with an antibiotic-resistant infection under compassionate use", "name": "Eric Nguyen", "handle": "exnx", "avatar": "https://pbs.twimg.com/profile_images/1640862340517335040/qcpMIN_b_200x200.jpg", "likes": 925, "rts": 163, "replies": 95, "views": 460868, "ts": 1792513517, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1280x720/o7F7SW5uTq0n6Cki.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1920x1080/PQ3lBUGHdIKOCD3U.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112578540013330432/img/iIkujuAjkAiQkxwh.jpg", "dur": 155}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112337141812564138", "url": "https://x.com/ArashVahdat/status/2112337141812564138", "text": "Exciting to see the community building on FastGen and pushing distillation techniques forward! 🚀\n\nThis cool new work builds on ideas from our PDD and PiFlow, exploring novel parameterizations of student heads. Great to see these ideas evolving!", "name": "Arash Vahdat", "handle": "ArashVahdat", "avatar": "https://pbs.twimg.com/profile_images/1110050283684429825/EF_j_77B_200x200.jpg", "likes": 60, "rts": 8, "replies": 0, "views": 3875, "ts": 1792455394, "media": [], "quote": {"id": "2111966225781924227", "url": "https://x.com/raywzy1/status/2111966225781924227", "text": "Excited to introduce Simplified Matching Distillation (SMD) for few-step diffusion🧵\n\nNo auxiliary score model. No adversarial training. No generator modification.\n\nYou will get:\n• Photorealistic appearance\n• High-quality dynamics\n• Memory-efficient training\n• Mode covering with diverse outputs\n\nSMD works well across images, video, joint audio–video, and 3D gen, validated across model scales up to 33B parameters.\n\nBesides, SMD supports:\n- Multi-teacher capability merging (like OPD in LLM)\n- Cross-model capability transfer\n- Bidirectional teacher to causal distillation\n\nFull release. Paper, code, model and data.\n\nProject Page: https://zjwfufu.github.io/SMD-Page/\nPaper: https://arxiv.org/abs/2610.18472\nCode: https://github.com/zjwfufu/SMD\nModel Card & Data: https://huggingface.co/zjwfufu/SMD\n\nDemo Video 👇", "name": "Ziyu Wan", "handle": "raywzy1", "avatar": "https://pbs.twimg.com/profile_images/1908641848018821126/lJqSrFgh_200x200.jpg", "likes": 490, "rts": 61, "replies": 13, "views": 30346, "ts": 1792366961, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111963793622499328/vid/avc1/1280x720/qyw5ZaX-giiQhXLz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111963793622499328/vid/avc1/1920x1080/86hCzVyZMu0QLk7M.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111963793622499328/img/Frf_RWufEpcTRZ1I.jpg", "dur": 115}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112643128993669534", "url": "https://x.com/jessexai_/status/2112643128993669534", "text": "Sam Altman: AGI might already be here\n\n\"I think there are a lot of people who would like look at our latest internal models\" \n\n\"And say this is like very AGI like.\"\n\n\"I think there are people who would say here's something I can point to\"\n\n\"That it doesn't do or it's really bad at and it's not.\"", "name": "jesse", "handle": "jessexai_", "avatar": "https://pbs.twimg.com/profile_images/2104534895678656512/ayrcLe5-_200x200.jpg", "likes": 17, "rts": 2, "replies": 4, "views": 4222, "ts": 1792528347, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112643029345370112/vid/avc1/1280x720/JXJ3__9jbG0UwRTZ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112643029345370112/vid/avc1/1920x1080/x-pm8izJ5SzFuYw2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112643029345370112/img/50_9G2U4QtHt1znF.jpg", "dur": 13}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112649827041321296", "url": "https://x.com/nytimes/status/2112649827041321296", "text": "From @TheAthleticFC: Erling Haaland is the latest convert to mate, a drink that has long taken football and the wider world by storm. https://nyti.ms/3UFkLX4", "name": "The New York Times", "handle": "nytimes", "avatar": "https://pbs.twimg.com/profile_images/1098244578472280064/gjkVMelR_200x200.png", "likes": 3337, "rts": 451, "replies": 146, "views": 738837, "ts": 1792529944, "media": [], "quote": null, "reply_to": null, "cat": "Sports", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112655787961295224", "url": "https://x.com/KanekoaTheGreat/status/2112655787961295224", "text": "ELON MUSK: SpaceX took the team that dominates space and “applied that same team to the deployment of terrestrial compute.”\n\n“This is a bit like the New York Yankees playing in little league. It’s not fair.”\n\nSpaceX puts almost 90% of all mass into orbit. China is roughly 6%. The rest of the world combined, including the rest of the U.S., is about 4%.\n\nThat’s “an order of magnitude greater” than all its space competitors combined.\n\nNow that team is deploying power, cooling, and infrastructure “vastly faster than anyone else, and may at some point be faster than everyone else combined.”\n\n“Let that sink in for a minute.”", "name": "KanekoaTheGreat", "handle": "KanekoaTheGreat", "avatar": "https://pbs.twimg.com/profile_images/1612188077333835776/qxjhM55m_200x200.jpg", "likes": 3744, "rts": 382, "replies": 31, "views": 102962, "ts": 1792531365, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112654843756400640/vid/avc1/1280x720/fZYqrNXVnRvVg4-z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112654843756400640/vid/avc1/1920x1080/xVHUqGrp9hr9xSWf.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112654843756400640/img/WI6lvb6AUmXBYQ14.jpg", "dur": 61}], "quote": null, "reply_to": null, "cat": "Sports", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112725454092370056", "url": "https://x.com/888Mooncat/status/2112725454092370056", "text": "Opensea's Mobile product is ready...  works beautifully across chains, tokens, you can also monitor social trading all in one place.  \n\nBig fan of OpenSea for years & now it gets even better!", "name": "888mooncat.eth", "handle": "888Mooncat", "avatar": "https://pbs.twimg.com/profile_images/2052200706753417217/VIZjQyfz_200x200.jpg", "likes": 9, "rts": 3, "replies": 3, "views": 306, "ts": 1792547975, "media": [], "quote": {"id": "2112654029595529229", "url": "https://x.com/opensea/status/2112654029595529229", "text": "OpenSea Mobile is now open to everyone.  \n\nEverything you own. Everything you trade. Everyone you trade with.  \n\nMemes, art, trading cards, perps. 25+ chains, all your wallets, one app.  \n\nTrade everything, together.", "name": "OpenSea", "handle": "opensea", "avatar": "https://pbs.twimg.com/profile_images/2112614202011537408/I-WGhmg2_200x200.jpg", "likes": 1768, "rts": 303, "replies": 545, "views": 199638, "ts": 1792530946, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588539883843586/vid/avc1/1280x720/3s97S5mJ1pQINx-m.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588539883843586/vid/avc1/1920x1080/nYtqw-Rkus3ooD7v.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588539883843586/img/79r4M1L0NEPlqY8F.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112582838432182317", "url": "https://x.com/ThePSF/status/2112582838432182317", "text": "After taking the PSF, Python, and Jython wikis read-only earlier this year, the PSF is pleased to share the wikis are back. Rebuilt on GitHub Pages with a fresh look, better security, and a new process to contribute. Learn more on the PSF Blog ➡️\nhttps://pyfound.blogspot.com/2026/10/wikis-relaunched.html", "name": "Python Software Foundation", "handle": "ThePSF", "avatar": "https://pbs.twimg.com/profile_images/1517584461017370624/DF3DpXUW_200x200.jpg", "likes": 22, "rts": 4, "replies": 2, "views": 6887, "ts": 1792513973, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112719581072556540", "url": "https://x.com/0xSolty/status/2112719581072556540", "text": "your 5-hour limit doesn't die while you work. it dies when you come back from a break and type <continue> one variable fixes most of it:\n\nexport CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS=100000\n\nthe prompt cache lives about an hour. leave a long session longer than that, and your next message re-reads the whole thing at full price.\n\nsince this month Claude Code fights back:\n\n→ at ~54 min idle it compacts the session, right before the cache expires\n→ by default only for sessions over 200K tokens\n→ the variable drops that to 100K, so mid-size sessions get saved too\n\ncheck it's on: /config → Idle compaction\n\nthe variable is one piece. the full setup has 3 more:\n\n→ the resume warning, shipped yesterday. resume an old chat and Claude Code tells you when it will eat a big part of your 5-hour limit. pick \"start new\" and just mention the old chat. Claude looks it up instead of reloading all of it\n→ CLAUDE_CODE_AUTO_COMPACT_WINDOW=200000. write the full number. \"200k\" was silently turning into a 100K window until this week's fix\n→ /usage at the end of a long day. it now flags max effort, workflows, always-on context and huge tool results, the usual limit killers\n\nthe full tree\n> long session goes idle\n> ~54 min: idle compaction, before the cache expires\n> sessions from 100K included with the variable\n> resume warning before an expensive reload\n> /usage shows what actually ate the limit\n\npaste this into Claude Code ↓\n\n\"Audit my Claude Code setup for usage-limit leaks:\n1. Add CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS=100000 to my shell profile.\n2. Check /config and make sure Idle compaction is on.\n3. If CLAUDE_CODE_AUTO_COMPACT_WINDOW is set anywhere, rewrite it as a full number (200000, not 200k).\n4. Add one line to CLAUDE.md: when I come back to an old task after a break, start a new session and reference the old one instead of resuming it.\nShow every change as a diff first. Don't apply anything until I say go.\"\n\n↳ http://code.claude.com/docs/en/changelog\n\nthe model isn't what's eating your limit. the coffee break is.", "name": "Solty", "handle": "0xSolty", "avatar": "https://pbs.twimg.com/profile_images/2105368881640390656/MQKCHyaj_200x200.jpg", "likes": 12, "rts": 2, "replies": 3, "views": 737, "ts": 1792546575, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112719259730096129/vid/avc1/720x900/eCqI49T1PRCxFb9i.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112719259730096129/vid/avc1/1080x1350/kp2MNZNx1a27fs8Q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112719259730096129/img/uUj8oF0iyxSX5Wl3.jpg", "dur": 40}], "quote": {"id": "2078784709253841039", "url": "https://x.com/Bober_smart/status/2078784709253841039", "text": "", "name": "Bober_smart", "handle": "Bober_smart", "avatar": "https://pbs.twimg.com/profile_images/2050347090543300608/p1PlS_hc_200x200.jpg", "likes": 2860, "rts": 386, "replies": 98, "views": 12338202, "ts": 1784455871, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112684911475994937", "url": "https://x.com/NICKIMINAJ/status/2112684911475994937", "text": "😅", "name": "Nicki Minaj", "handle": "NICKIMINAJ", "avatar": "https://pbs.twimg.com/profile_images/2044505524234797056/kKiF5v8h_200x200.jpg", "likes": 3083, "rts": 401, "replies": 89, "views": 131429, "ts": 1792538309, "media": [], "quote": {"id": "2112680862332375539", "url": "https://x.com/priscy776/status/2112680862332375539", "text": "Not her asking if cowgirls work with him 😭😭😂😂😂... she's so funny 🤣 #MillionDollarPitch", "name": "Priscy 𓏲ּ𝄢⋆", "handle": "priscy776", "avatar": "https://pbs.twimg.com/profile_images/2030592646301782016/-0k0IlYI_200x200.jpg", "likes": 819, "rts": 59, "replies": 10, "views": 96888, "ts": 1792537343, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112680204799819776/vid/avc1/630x360/pASIMLgNmuATHZCM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112680204799819776/vid/avc1/1080x616/pS6LiFvxgoguqokC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112680204799819776/img/AWRNn4UoH1pewnFw.jpg", "dur": 37}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.02, "thread": [], "tier": "skim"}, {"id": "2112212186068082788", "url": "https://x.com/pally/status/2112212186068082788", "text": "Manage your LinkedIn DMs from iMessage!\n\nPally now lets you:\n- Connect your LI account\n- Review and clean up your connection requests\n- Search over your connections in natural language\n- Manage your LI inbox and send replies\n\nThe sign-in and connection remains fully local, with our Mac companion app, so your sign in never leaves your machine!\n\nYou keep full control, and full privacy.\n\nTry it today!", "name": "Pally", "handle": "pally", "avatar": "https://pbs.twimg.com/profile_images/2039549300057976832/pee4Yrn4_200x200.jpg", "likes": 77, "rts": 5, "replies": 15, "views": 4808, "ts": 1792425602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111141920370032640/vid/avc1/1280x720/L2tVqPKAdkWIRZgN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111141920370032640/vid/avc1/1920x1080/L1gSEw6ABboWAUum.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111141920370032640/img/mGMGJA67WZ4sWWfk.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "skim"}, {"id": "2112595426537091508", "url": "https://x.com/Box/status/2112595426537091508", "text": "“The systems of record that agents have access to will grow in importance, because you will want to make sure that those systems are governing the rules of the road for these agent swarms to operate in.”\n\n@levie on @CNBC discussed why enterprise ROI from agent swarms relies on the systems underneath them.", "name": "Box", "handle": "Box", "avatar": "https://pbs.twimg.com/profile_images/2095961122147008512/lZm3p6aN_200x200.png", "likes": 16, "rts": 6, "replies": 1, "views": 101025, "ts": 1792516974, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112594920833978368/vid/avc1/1280x720/VPOJDNm5XLfMPDKI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112594920833978368/vid/avc1/1920x1080/3rsMamzLEi6CBBxa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112594920833978368/img/3BeTC-I31Ki2pbV5.jpg", "dur": 84}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "skim"}, {"id": "2112621018753974486", "url": "https://x.com/zhenthebuilder/status/2112621018753974486", "text": "Replit Japan office is opening, one more place to visit when flying to Japan now", "name": "Zhen Li", "handle": "zhenthebuilder", "avatar": "https://pbs.twimg.com/profile_images/2024726443557867521/tQzYsJzE_200x200.jpg", "likes": 30, "rts": 1, "replies": 0, "views": 808, "ts": 1792523076, "media": [], "quote": {"id": "2112596075240693860", "url": "https://x.com/Replit/status/2112596075240693860", "text": "Tokyo, we’re here! 🇯🇵 @Replit is opening its Japan office, bringing enterprise app and agent building closer to the businesses shaping Japan’s future. (Space is limited. Registration subject to approval.)\n\nJapan, let’s build what’s next.\n\nJoin us November 5–6 for four experiences:\n\n🏢 Nov 5 (Thu) Morning | Replit × @Microsoft\nTurn enterprise data into a working business dashboard with AI.\n📍 CIC Tokyo, Toranomon Hills | 10 AM–12 PM\n👉 Register: https://replit-microsoft-tokyo-nov-5.replit.app/workshop/\n\n🚀 Nov 5 (Thu) Afternoon | Replit × Endeavor Japan: Workshop\nBuild an app or agent to help bring your next big idea to life.\n📍  X-BASE SHIBUYA | 1:30–3 PM\n👉 Register: Workshop 1:30 - 3 PM: https://luma.com/3iwhwri1 & Panel: 3 - 6 PM: https://luma.com/180o9qr0\n\n🚀 Nov 5 (Thu) Afternoon | Replit × Endeavor Japan: Panel & Networking\nJapanese enterprises competing in the AI era.\n📍 X-BASE SHIBUYA | 3–6 PM\n👉Register: https://luma.com/180o9qr0\n\n🚀 Nov 6 (Fri) Evening | Replit Japan Opening Night\nCelebrate Replit’s official launch in Japan with the Replit team.\n📍 Shin-Marunouchi Building 10F | 7–9 PM\n👉Register:  https://luma.com/zhgvz6u2", "name": "Replit ⠕", "handle": "Replit", "avatar": "https://pbs.twimg.com/profile_images/2092066596915466240/TwZ32AYK_200x200.jpg", "likes": 56, "rts": 15, "replies": 5, "views": 8825, "ts": 1792517129, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112595649132920832/vid/avc1/720x900/iYJwUdXv4UBcwuNn.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112595649132920832/vid/avc1/1080x1350/qKhe-Pl1xKaKdSmc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112595649132920832/img/Y6eHMgZD72y6HDmZ.jpg", "dur": 16}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "skim"}, {"id": "2112670685042446809", "url": "https://x.com/Flandermaxx/status/2112670685042446809", "text": "WHOEVER LEAKED THIS JEV DECISION MODULE SHOULD BE RUNNING YOUR GTM\n\nI thought spinning up an AI sales op meant a Zapier chain, 300 cold emails a day, and a block list by week two.\n\nApparently not.\n\nThis module's setup is much more interesting:\n\n→ BRIEF locks the goal to $2,000/mo across 14 days with opus-5.5 on delegate mode, no scope creep, no \"while you're at it\"\n→ SOURCES scopes the whole run to one city and one niche (Austin, dental), 248 records max, no vertical mixing on retry\n→ KB.INDEX loads prices, policies and 48 FAQs into a 1,536-dim vector DB at $25/mo, 0.94 recall, before a single outreach fires\n→ QUALIFY filters 272 chats down to 54 leads at a 1-in-5 rate, writes a typed lead.json (name, need, budget), no \"maybe interested\"\n→ HUMAN GATE compares p(close) against 0.85, drafts the send above, asks you below, but every send still waits for your yes, flags 7 drafts that tried to go out without a sourced price\n\nso you get:\n\nBriefs locked. Sources scoped. Leads typed. Sends gated.\n\nthe interesting part isn't automating sales harder.\nit's giving every send a gate the agent can't fire past without you.\n\nInstead of a cold-email chain burning your domain by Tuesday, you run 14 days on $0 infra, $25/mo vector DB, 1 of 4 clients closed at $500/mo modeled, and the gate stops every send that isn't sourced.\n\nLock the brief. Scope the source. Gate the send.", "name": "Flandermaxx", "handle": "Flandermaxx", "avatar": "https://pbs.twimg.com/profile_images/2096231413234515968/1PYpYwc6_200x200.jpg", "likes": 20, "rts": 0, "replies": 4, "views": 1003, "ts": 1792534917, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112669533810896896/vid/avc1/720x900/t81B8aauwvJtlQWY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112669533810896896/vid/avc1/1080x1350/LutN49PRyNTStsh9.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112669533810896896/img/KDQXMPoURgNAU1IM.jpg", "dur": 25}], "quote": {"id": "2100984487802708306", "url": "https://x.com/0xCodila/status/2100984487802708306", "text": "Jev is the \"Internet\" moment for the AI industry\n\nIt tells your agents and LLMs what to do next, in milliseconds and at almost zero cost\n\nIf you set it up correctly, you will have the AI engineer’s stack for 2028\n\nIn this article, I show you how https://x.com/i/article/2077744776565149697", "name": "codila", "handle": "0xCodila", "avatar": "https://pbs.twimg.com/profile_images/2064453666661441536/nj8n8Mei_200x200.jpg", "likes": 3485, "rts": 436, "replies": 94, "views": 2284716, "ts": 1789748710, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "skim"}, {"id": "2112519477417963919", "url": "https://x.com/0xzynq/status/2112519477417963919", "text": "I keep thinking about how much of research is just retyping someone else’s paper into code\n\nso I tried handing that part off. 16 claude code agents, a queue of arxiv papers, one rule: read it, rebuild the simulation, compare against the paper’s figures. I don’t touch anything\n\nthis is the lorenz one going from a broken half-attractor to the real thing. the first few seconds look wrong on purpose, that’s the agents guessing constants. then the “flag missing constants” agent kicks in and it starts converging\n\nend of the run:\n\n97 papers\n41 reference figures checked\n19 different methods\n0 needing human review\nmy favorite detail: it computed λ₁ ≈ 0.906 on its own. if you’ve ever done a dynamics class you know that number. seeing it pop up unprompted made me trust the rest a bit more\nwhat it doesn’t prove: that any of these papers are correct. it only proves that our code produces the same pictures they did. that’s reproduction, not peer review\nbut going from pdf to a working notebook with zero manual steps is wild to me\n\nwhat’s the most painful paper you’ve ever had to reproduce by hand?", "name": "ZYNQ", "handle": "0xzynq", "avatar": "https://pbs.twimg.com/profile_images/2104290095876444160/KVyGPPxc_200x200.jpg", "likes": 27, "rts": 1, "replies": 8, "views": 787, "ts": 1792498866, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112519278171680768/vid/avc1/720x900/kjaG0UpQpIzSmrvY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112519278171680768/vid/avc1/1080x1350/YHy7s8SQQWG71o1O.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112519278171680768/img/8VRzymcmn4uwHfub.jpg", "dur": 22}], "quote": {"id": "2078784709253841039", "url": "https://x.com/Bober_smart/status/2078784709253841039", "text": "", "name": "Bober_smart", "handle": "Bober_smart", "avatar": "https://pbs.twimg.com/profile_images/2050347090543300608/p1PlS_hc_200x200.jpg", "likes": 2860, "rts": 386, "replies": 98, "views": 12338228, "ts": 1784455871, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "skim"}, {"id": "2112618909040091445", "url": "https://x.com/CopyRebeldia/status/2112618909040091445", "text": "La industria farmacéutica abandonó a las víctimas de escorpión porque no eran negocio.\nClaude no necesitaba que fueran negocio.\n\nEn 64 horas, casi solo, diseñó 318.484 proteínas que no existían para bloquear sus neurotoxinas. Dos laboratorios probaron 211 diseños y 17 se agarraron a la toxina.\n\nLas dos mejores van contra un alacrán mexicano.\n\nEl antídoto de siempre todavía sale de la sangre de caballos. El próximo podría salir de una IA.", "name": "CopyRebeldia", "handle": "CopyRebeldia", "avatar": "https://pbs.twimg.com/profile_images/2034089342205833216/_D4TRnCt_200x200.jpg", "likes": 21, "rts": 4, "replies": 0, "views": 2815, "ts": 1792522573, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGHs0za8AABEjD.jpg?name=orig"}], "quote": {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5775, "rts": 455, "replies": 393, "views": 1191640, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.01, "thread": [], "tier": "skim"}]);